mapper.select:
SELECT `r`.`id` as processInstanceId, `r`.`start_user_id`, `r`.`start_user_name`, `r`.`organization_id`, `r`.`organization_name`, `r`.`result` AS `status`, `r`.`instance_name`, `r`.`start_user_info` AS `start_user_info`, `r`.`application_code` AS `business_model`, `r`.`business_type` AS `business_type`, `r`.`tenant` AS `tenant`, COALESCE(`r`.`result`, 'ACTIVE') AS `state`, `t`.`user_ids` AS `assignee`, `p`.`START_TIME_` AS `submitedTime`, v.`TEXT_` as formNo, vt.`NAME_` as activeNodeName FROM `copy_log` `t` inner JOIN `process_instance_running` `r` ON `r`.`id` = `t`.`process_instance_id` LEFT JOIN `act_hi_procinst` `p` ON `p`.`PROC_INST_ID_` = `t`.`process_instance_id` inner join `act_hi_varinst` as v on r.`id`= v.`PROC_INST_ID_` and v.`NAME_`='formNo' inner join `act_hi_taskinst` as vt on r.`id`= vt.`PROC_INST_ID_`
p.`START_TIME_` BETWEEN #{query.submitTime.begin} AND #{query.submitTime.end}
and r.`business_type`=#{query.businessType}
and r.`result` is null
and r.`result` = #{query.status}
and t.`user_ids` like concat('%',#{userId},'%')
r.`start_user_id` =#{query.startUserId}
r.`organization_id` =#{query.organizationId}
group by r.`id` order by p.`START_TIME_` desc
